-- ISSUE-HYGIENE-5 (2026-10-26, pillar autonomy; follows hygiene-1 to -4): 5 open agent_issues closed with evidence an independent review and a live re-measurement agreed on.
--
-- HOW THE LIST WAS MADE (read-only against live qnfo-audit, the repository and the fleet's hosts, 2026-10-26)
--   5 issues, one fix (q08-mind 2.2.1), reviewed independently and re-measured live 2026-10-26T09:52Z
--   The five issues share one fix, q08-mind 2.2.1 (PR 4537, merged and live): an implementer repaired the two source links, an independent adversarial reviewer re-checked the
--   change against Crossref and the live site (verdict ship), and the evidence below was re-measured on the live site and Crossref by the session before this file was written.
--   Nothing is closed as wontfix and no metric target was changed. The evidence of each issue is the text below, standalone and dated.
--
-- MECHANISM (as hygiene-1): issue_fold_ledger keeps the before-state of every row, the contracts leave the closing path, the close names its channel
--   (workflow:ISSUE-HYGIENE-1 session-sweep-2026-10-26-doi), the evidence goes into issue_triage and the live trigger triage_close_sync_issue_upd closes the issue; no trigger is added.
--   Rows written: issue_fold_ledger 5, then at most 5 issue closes with their lifecycle rows. No DELETE, no DROP.
--
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE issue_triage SET triage_state = (SELECT f.triage_state FROM issue_fold_ledger f WHERE f.issue_id = issue_triage.issue_id AND f.rule = 'session-sweep-2026-10-26-doi' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1), close_evidence = (SELECT f.triage_close_evidence FROM issue_fold_ledger f WHERE f.issue_id = issue_triage.issue_id AND f.rule = 'session-sweep-2026-10-26-doi' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1), reopened_count = (SELECT f.triage_reopened_count FROM issue_fold_ledger f WHERE f.issue_id = issue_triage.issue_id AND f.rule = 'session-sweep-2026-10-26-doi' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1), triaged_at = (SELECT f.triage_triaged_at FROM issue_fold_ledger f WHERE f.issue_id = issue_triage.issue_id AND f.rule = 'session-sweep-2026-10-26-doi' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1) WHERE issue_id IN (SELECT issue_id FROM issue_fold_ledger WHERE rule = 'session-sweep-2026-10-26-doi' AND applied = 1); UPDATE agent_issues SET status = 'open', close_channel = (SELECT f.agent_close_channel FROM issue_fold_ledger f WHERE f.issue_id = agent_issues.id AND f.rule = 'session-sweep-2026-10-26-doi' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1), updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000 WHERE id IN (SELECT issue_id FROM issue_fold_ledger WHERE rule = 'session-sweep-2026-10-26-doi' AND applied = 1) AND status = 'closed' AND close_channel = 'workflow:ISSUE-HYGIENE-1 session-sweep-2026-10-26-doi'; UPDATE remediation_contracts SET status = (SELECT f.contract_status FROM issue_fold_ledger f WHERE f.contract_class = remediation_contracts.class AND f.rule = 'session-sweep-2026-10-26-doi' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1), last_verdict = (SELECT f.contract_last_verdict FROM issue_fold_ledger f WHERE f.contract_class = remediation_contracts.class AND f.rule = 'session-sweep-2026-10-26-doi' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1) WHERE class IN (SELECT contract_class FROM issue_fold_ledger WHERE rule = 'session-sweep-2026-10-26-doi' AND applied = 1 AND contract_class IS NOT NULL) AND last_verdict LIKE 'superseded:closure-superseded%'

-- 1. The ledger rows: each carries the before-state and the evidence
INSERT INTO issue_fold_ledger (issue_id, rule, successor_id, evidence, agent_status, agent_updated_at, agent_close_channel, triage_state, triage_close_evidence, triage_reopened_count, triage_triaged_at, contract_class, contract_status, contract_last_verdict, contract_last_attempt_at) SELECT m.id, 'session-sweep-2026-10-26-doi', v.succ, v.ev || ' ISSUE-HYGIENE-1 ' || strftime('%Y-%m-%d', 'now'), m.status, m.updated_at, m.close_channel, t.triage_state, t.close_evidence, t.reopened_count, t.triaged_at, c.class, c.status, c.last_verdict, c.last_attempt_at FROM (SELECT 100462 AS id, 'verified: all three defects are gone at 2026-10-26T09:52Z. D1: mind.q08.org/start links five /q/ entries (gollwitzer-implementation-intentions, killingsworth-gilbert, nisbett-wilson, osc-2015, vazire-soka) and each returns HTTP 200, so no slug is dropped; START in q08-mind/worker.js names the five. D2 (neff-compassion DOI, closed as 100468) and D3 (doris-situationism DOI, closed as 100467) are fixed by PR 4537 (q08-mind 2.2.1, live), with 10.1080/15298860309027 for D2 because the ticket''s ...032 is a different paper.' AS ev, NULL AS succ UNION ALL SELECT 100467 AS id, 'verified: q08-mind 2.2.1 is live (PR 4537; /health version 2.2.1) and mind.q08.org/api/entries.json at 2026-10-26T09:52Z carries 10.1017/cbo9781139878364 and no longer carries 10.1017/CBO9780511613292. Crossref returns ''Lack of Character'' (Doris) with HTTP 200 for the new DOI and 404 for the old one; q08-mind/entries-doi.test.mjs pins the link to the Crossref title and author.' AS ev, NULL AS succ UNION ALL SELECT 100468 AS id, 'verified: q08-mind 2.2.1 is live (PR 4537) and mind.q08.org/api/entries.json at 2026-10-26T09:52Z carries 10.1080/15298860309027 and no longer carries the Brown and Ryan DOI 10.1037/0022-3514.84.4.822. Crossref: 10.1080/15298860309027 is Neff, ''The Development and Validation of a Scale to Measure Self-Compassion'' (the paper the entry''s own text describes); the ticket''s proposed ...032 is a different Neff paper (the conceptualization), so ...027 was used. q08-mind/entries-doi.test.mjs pins it.' AS ev, NULL AS succ UNION ALL SELECT 1000150 AS id, 'moot: duplicate of 100468, filed because the code task read the old path mind/data/entries-b.json (404). The same defect is fixed by PR 4537 (q08-mind 2.2.1, live): mind.q08.org/api/entries.json at 2026-10-26T09:52Z carries 10.1080/15298860309027 and no longer carries 10.1037/0022-3514.84.4.822; 100468 closes in the same migration with the full evidence.' AS ev, NULL AS succ UNION ALL SELECT 1000151 AS id, 'moot: duplicate of 100467, filed because the code task read the old path mind/data/entries-a.json (404). The same defect is fixed by PR 4537 (q08-mind 2.2.1, live): mind.q08.org/api/entries.json at 2026-10-26T09:52Z carries 10.1017/cbo9781139878364 and no longer carries 10.1017/CBO9780511613292; 100467 closes in the same migration with the full evidence.' AS ev, NULL AS succ) v JOIN agent_issues m ON m.id = v.id JOIN issue_triage t ON t.issue_id = m.id LEFT JOIN remediation_contracts c ON c.class = 'issue-' || m.id WHERE m.status = 'open' AND NOT EXISTS (SELECT 1 FROM issue_fold_ledger f WHERE f.issue_id = m.id AND f.applied = 0);

-- 2. Settle the contracts, name the channel, close through the triage row, mark the ledger
UPDATE remediation_contracts SET status = 'superseded', last_verdict = 'superseded:closure-superseded (ISSUE-HYGIENE-1)', last_attempt_at = datetime('now') WHERE class IN (SELECT f.contract_class FROM issue_fold_ledger f WHERE f.applied = 0 AND f.contract_class IS NOT NULL) AND status IN ('monitoring', 'escalated', 'active', 'holding', 'needs-machine-probe', 'probe-review-refused');
UPDATE agent_issues SET close_channel = 'workflow:ISSUE-HYGIENE-1 ' || (SELECT f.rule FROM issue_fold_ledger f WHERE f.issue_id = agent_issues.id AND f.applied = 0 ORDER BY f.id DESC LIMIT 1) WHERE status = 'open' AND id IN (SELECT issue_id FROM issue_fold_ledger WHERE applied = 0);
UPDATE issue_triage SET triage_state = 'closed', triaged_at = datetime('now'), close_evidence = (SELECT f.evidence FROM issue_fold_ledger f WHERE f.issue_id = issue_triage.issue_id AND f.applied = 0 ORDER BY f.id DESC LIMIT 1) WHERE issue_id IN (SELECT f.issue_id FROM issue_fold_ledger f JOIN agent_issues a ON a.id = f.issue_id WHERE f.applied = 0 AND a.status = 'open');
UPDATE agent_issues SET status = 'closed', updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000 WHERE status = 'open' AND id IN (SELECT f.issue_id FROM issue_fold_ledger f JOIN issue_triage t ON t.issue_id = f.issue_id WHERE f.applied = 0 AND t.triage_state = 'closed' AND t.close_evidence = f.evidence);
UPDATE issue_fold_ledger SET applied = 1, applied_at = datetime('now') WHERE applied = 0 AND (SELECT a.status FROM agent_issues a WHERE a.id = issue_fold_ledger.issue_id) <> 'open';
